import * as THREE from 'three';
import {OrbitControls} from 'three/addons/OrbitControls.js';
const $=s=>document.querySelector(s),f=(x,n=2)=>x.toLocaleString('es-CO',{maximumFractionDigits:n,minimumFractionDigits:n}),g=9.81;
const configs={projectile:{title:'Lanza. Observa. Comprende.',intro:'La velocidad horizontal se mantiene; la vertical cambia por la gravedad.',params:[['Rapidez inicial',5,25,14,1,'m/s'],['Ángulo de lanzamiento',15,75,45,1,'°']],notes:'Sin aire, salida y llegada a la misma altura. Escena a escala: una división principal de la cuadrícula equivale a 1 m. Flechas escaladas para poder comparar sus direcciones.',lessons:[['Dos movimientos a la vez','En horizontal no hay aceleración. En vertical, la gravedad reduce la velocidad de subida y aumenta la de bajada.','x = v₀ cos(θ)t'],['El punto más alto','La velocidad vertical es cero en la cima, pero la horizontal continúa. La aceleración sigue apuntando hacia abajo.','y = v₀ sin(θ)t − ½gt²'],['El alcance','Depende de la rapidez y del ángulo. Esta expresión supone la misma altura de salida y llegada.','R = v₀² sin(2θ) / g']]},circle:{title:'Cambiar de dirección es acelerar.',intro:'La rapidez es constante, pero la velocidad gira. La aceleración siempre apunta hacia el centro.',params:[['Radio',2,8,4,.5,'m'],['Rapidez',1,8,4,.5,'m/s']],notes:'Movimiento circular uniforme en un plano horizontal. Una división equivale a 1 m. Flechas de longitud visual normalizada: representan direcciones; los valores aparecen debajo.',lessons:[['Velocidad tangente','La velocidad apunta por la tangente a la circunferencia. Si desaparece la fuerza hacia el centro, el cuerpo sigue por esa tangente.','v = ωr'],['Aceleración centrípeta','No aumenta la rapidez: cambia la dirección. Duplicar la rapidez cuadruplica la aceleración necesaria.','a = v² / r'],['Una vuelta completa','El período es el tiempo de una vuelta. A mayor radio y misma rapidez, tarda más.','T = 2πr / v']]},pendulum:{title:'La energía va y viene.',intro:'Observa las barras: la energía potencial se convierte en cinética y regresa en cada oscilación.',params:[['Longitud',1,5,3,.25,'m'],['Amplitud',5,35,25,1,'°']],notes:'Péndulo ideal de 1 kg sin fricción. Movimiento calculado con conservación de energía mediante integración numérica de θ″ = −(g/L)sinθ. Las barras muestran joules; el período indicado es la aproximación para ángulos pequeños.',lessons:[['En los extremos','La rapidez es cero y la energía potencial es máxima. El péndulo empieza a regresar por el torque de la gravedad.','Ep = mgL(1 − cosθ)'],['En el centro','La energía potencial es mínima y la cinética máxima. La velocidad es tangente al arco.','Ec = ½m(Lω)²'],['La longitud importa','Un péndulo más largo oscila más lento. Para amplitudes grandes el período real supera esta aproximación.','T ≈ 2π√(L/g)']]},gears:{title:'Dientes que transmiten movimiento.',intro:'El engranaje pequeño impulsa al grande. En el punto de contacto, sus dientes avanzan a la misma velocidad tangencial.',params:[['Velocidad de entrada',5,60,20,5,'rpm'],['Dientes del engranaje B',16,40,32,8,'']],notes:'Par de engranajes exteriores ideal: A tiene 16 dientes, ambos comparten módulo. Perfil de dientes ilustrativo, no diseñado para fabricación. Sin pérdidas ni deslizamiento. Se dibujan los círculos primitivos, donde se cumple ωA·rA = −ωB·rB.',lessons:[['Sentidos opuestos','Cada diente empuja al siguiente. Dos engranajes exteriores conectados giran en sentidos opuestos.','ωB = −ωA · ZA / ZB'],['Menos velocidad, más torque','Con más dientes en la salida se reduce su velocidad y aumenta su torque en el modelo ideal.','τB / τA = ZB / ZA'],['La energía no se multiplica','En una transmisión ideal se conserva la potencia. Ganar torque implica perder velocidad angular.','P = τ · ω']]}};

configs.compression={title:'¿Por qué el aire cede y el agua casi no?',intro:'Compara dos cilindros cerrados con el mismo volumen inicial y la misma presión aplicada. El gas reduce mucho su volumen; el líquido casi no.',params:[['Presión máxima añadida',0,400,200,20,'kPa'],['Volumen inicial',50,150,100,10,'mL']],notes:'Gas ideal a temperatura constante: presión absoluta inicial de 100 kPa. Agua con módulo volumétrico constante K = 2,2 GPa. No hay fugas. La presión sube y baja lentamente en un ciclo ilustrativo de 8 s. Los puntos representan moléculas de forma esquemática, no a escala.',lessons:[['Comprimir es reducir volumen','Las moléculas del gas tienen mucho espacio entre ellas. Al empujar el pistón se acercan; el número de moléculas no cambia.','Gas: P absoluta · V = constante'],['El líquido también cede, pero muy poco','El agua no es perfectamente incompresible. Su gran resistencia a reducir volumen se mide con el módulo volumétrico K.','Agua: ΔV/V ≈ −ΔP/K'],['Presión no significa fuerza','La presión es la fuerza repartida entre el área. El manómetro mide presión respecto al ambiente; la ley del gas usa presión absoluta.','P absoluta = P ambiente + P añadida']]};
configs.hydraulic={title:'Una fuerza pequeña levanta una carga mayor.',intro:'El pistón pequeño empuja el líquido y el grande sube. Compara sus recorridos: la ganancia de fuerza se paga con distancia.',params:[['Fuerza de entrada',10,100,10,10,'N'],['Relación de áreas A₂/A₁',2,10,10,1,'×']],notes:'Prensa ideal, movimiento lento, sin pérdidas y líquido incompresible. A₁ = 1 cm². Se desprecia la diferencia de presión por altura y el peso de los pistones. El recorrido de entrada va de 0 a 2 cm y regresa; su ritmo es ilustrativo, no se calcula a partir de la fuerza.',lessons:[['Pascal: transmite presión','La misma subida de presión actúa bajo ambos pistones. El pistón grande recibe más fuerza porque tiene más área.','F₁/A₁ = F₂/A₂'],['Conservación del volumen','El líquido que sale del cilindro pequeño entra en el grande. Si el área de salida es diez veces mayor, su recorrido es diez veces menor.','A₁ · d₁ = A₂ · d₂'],['No aparece energía gratis','La salida multiplica la fuerza, pero recorre menos distancia. En el modelo ideal, el trabajo de entrada y salida coincide.','F₁ · d₁ = F₂ · d₂']]};
configs.flow={title:'Un paso estrecho acelera el agua.',intro:'Sigue las partículas: el mismo caudal atraviesa ambas secciones. Al reducir el área, la velocidad aumenta.',params:[['Caudal',.2,2,1,.1,'L/s'],['Área de salida',2,8,4,1,'cm²']],notes:'Agua en régimen estacionario, incompresible, conducto horizontal sin pérdidas. Área de entrada: 8 cm². Diámetros ampliados para hacerlos visibles; longitud de 8 m. Se prescribe el caudal: una instalación real necesita una diferencia de presión para mantenerlo.',lessons:[['Caudal: volumen por segundo','El caudal Q expresa cuánto líquido atraviesa una sección por unidad de tiempo. No es lo mismo que la velocidad.','Q = A · v'],['Continuidad','Con el mismo caudal, reducir el área a la mitad duplica la velocidad. Los puntos conservan su flujo al pasar por el estrechamiento.','A₁v₁ = A₂v₂'],['Presión y velocidad','En este modelo horizontal ideal, el aumento de velocidad se acompaña de una caída de presión estática. No implica crear energía.','P₁ − P₂ = ½ρ(v₂² − v₁²)']]};

configs.current={title:'Tensión empuja. Corriente circula.',intro:'Sigue las cargas por un circuito cerrado. Cambia entre continua y alterna para ver la diferencia entre avanzar y oscilar.',params:[['Tensión (DC o RMS en AC)',1,24,12,1,'V'],['Resistencia',2,40,12,2,'Ω']],notes:'Circuito ideal puramente resistivo. En continua, I = V/R. En alterna sinusoidal, frecuencia fija de 50 Hz y tensión indicada RMS. La animación AC se ralentiza 100 veces; las partículas muestran el sentido de corriente convencional, no la velocidad real de electrones ni de propagación de energía.',lessons:[['Tres ideas distintas','Tensión: diferencia de potencial, en voltios. Corriente: carga que pasa por segundo, en amperios. Resistencia: oposición al paso, en ohmios.','I = V / R'],['Continua y alterna','En DC la corriente mantiene su sentido. En AC cambia de signo periódicamente. Los electrones metálicos se desplazan en sentido opuesto a la corriente convencional.','v(t) = √2 · V RMS · sin(2πft)'],['La resistencia transforma energía','La potencia media disipada aumenta con el cuadrado de la tensión para una resistencia fija. RMS permite comparar el calentamiento de AC y DC.','P media = V RMS² / R']]};
configs.alternator={title:'Del giro a la tensión eléctrica.',intro:'El rotor mueve un campo magnético frente a una bobina fija. Al cambiar el flujo magnético aparece una tensión inducida.',params:[['Velocidad del rotor',600,3600,1800,300,'rpm'],['Número de polos',2,8,4,2,'']],notes:'Alternador esquemático ideal en circuito abierto: produce tensión, pero sin carga no circula corriente externa. Flujo enlazado máximo supuesto de 0,1 Wb·vuelta, constante. Una bobina representativa; no es un plano de devanado. Giro y onda ralentizados 100 veces.',lessons:[['Inducción: cambia el flujo','La tensión depende de qué tan rápido cambia el flujo magnético enlazado con la bobina. Un campo constante respecto a ella no genera una tensión sostenida.','e = −d(NΦ) / dt'],['Polos y frecuencia','Cada par de polos produce un ciclo eléctrico por vuelta mecánica. Con 4 polos a 1 800 rpm se obtienen 60 Hz.','f = polos · rpm / 120'],['Hace falta energía mecánica','Al conectar una carga aparece corriente y un torque que se opone al giro. El motor o la turbina debe aportar energía para mantener la velocidad.','Potencia mecánica → potencia eléctrica']]};
configs.threephase={title:'Tres ondas, un ritmo compartido.',intro:'Las fases A, B y C tienen igual frecuencia y amplitud, pero llegan a su máximo en momentos distintos: están separadas 120° eléctricos.',params:[['Tensión de fase RMS',12,240,120,12,'V'],['Frecuencia',10,60,50,10,'Hz']],notes:'Fuente trifásica equilibrada, conexión estrella con neutro y tres resistencias idénticas de 12 Ω. Factor de potencia 1. V línea = √3 · V fase solo para esta conexión. Las flechas son fasores de tensión, no piezas físicas. Visualización ralentizada 100 veces.',lessons:[['120° no significa 120 voltios','Es un tercio de ciclo. Si A empieza a subir, B y C están en otros puntos de la misma onda. Sus valores instantáneos suman cero en este sistema equilibrado.','vA + vB + vC = 0'],['Fase, línea y neutro','La tensión de fase se mide entre fase y neutro; la de línea, entre dos fases. En estrella equilibrada, la corriente de línea coincide con la de fase y la del neutro es cero.','V línea = √3 · V fase'],['Tres aportes se complementan','Con estas cargas equilibradas, la potencia total es constante aunque la de cada fase varíe. Con cargas reactivas la corriente puede desfasarse respecto a su tensión.','P total = 3 · V fase RMS · I fase RMS']]};
configs.pneumatic={title:'El aire comprimido produce movimiento.',intro:'Una válvula dirige el aire a un lado del pistón y deja escapar el del otro. Después invierte los caminos para que el vástago regrese.',params:[['Presión de alimentación',1,8,4,1,'bar'],['Diámetro del pistón',20,80,40,10,'mm']],notes:'Cilindro de doble efecto, vástago de 10 mm, presión manométrica constante y escape a la atmósfera. Fuerzas ideales sin fricción, contrapresión ni aceleración. Recorrido prescrito para explicar la secuencia; no predice el tiempo real de avance. El depósito se supone alimentado por un compresor.',lessons:[['Comprimir y almacenar','El compresor usa energía para meter aire a presión en un depósito. El aire se comprime y almacena energía; un regulador fija la presión de alimentación.','1 bar = 100 000 Pa'],['La válvula decide el sentido','En avance alimenta la cámara sin vástago y descarga la otra. En retorno intercambia alimentación y escape. El aire descargado sale al ambiente.','Alimentar un lado + descargar el otro'],['La fuerza cambia al regresar','En avance actúa toda el área del pistón. En retorno el vástago resta área, así que la fuerza ideal de retorno es menor a la misma presión.','F avance = pA · F retorno = p(A − A vástago)']]};

configs.atmosphere={title:'Vivimos en el fondo de un océano de aire.',intro:'La gravedad mantiene la atmósfera alrededor de la Tierra. Al subir, queda menos aire encima y la presión disminuye. Explora la altura con el control.',params:[['Altitud',0,10000,0,100,'m'],['Área de la superficie',1,100,10,1,'cm²']],notes:'Atmósfera idealizada: P = 101,325(1 − 0,0065h/288,15)^5,25588 kPa, válida aquí de 0 a 10 km. No es un pronóstico: el tiempo atmosférico cambia los valores reales. Paisaje, partículas y alturas exagerados para enseñar. La fuerza mostrada es sobre una cara; la fuerza neta depende de la presión en la otra.',lessons:[['El aire tiene masa','La presión macroscópica está ligada al peso del aire de arriba. A escala microscópica, las moléculas chocan contra las superficies y les transfieren impulso.','1 atm = 101 325 Pa = 101,325 kPa'],['La presión actúa en todas direcciones','No empuja solo hacia abajo. Un gas en reposo ejerce presión normal a cualquier superficie: hacia los lados, arriba y abajo.','F sobre una cara = P · A'],['¿Por qué no nos aplasta?','No estamos vacíos por dentro. Las presiones y las fuerzas internas de los tejidos equilibran gran parte del empuje exterior. Lo que suele deformar un objeto es la diferencia de presión.','F neta = (P interior − P exterior) · A']]};
configs.barometer={title:'Una columna que pesa lo mismo que el aire.',intro:'El aire empuja el líquido del depósito. La columna se sostiene cuando su peso equilibra esa presión. Sobre la columna hay un espacio casi vacío.',params:[['Presión atmosférica',60,110,101,1,'kPa'],['Densidad del líquido',1000,13600,13600,100,'kg/m³']],notes:'Barómetro ideal: presión sobre la columna despreciable, g = 9,81 m/s², depósito grande de nivel constante. Se ignoran vapor, capilaridad y temperatura. 13 600 kg/m³ aproxima el mercurio y 1 000 kg/m³ el agua. La escala vertical se ajusta con la densidad; consulta siempre la altura numérica. Es una simulación, no un experimento con mercurio.',lessons:[['Un equilibrio de presiones','A la altura de la superficie del depósito, la presión dentro y fuera del tubo debe coincidir. La presión de la columna es su densidad por gravedad por altura.','P atm ≈ ρgh'],['El líquido más denso necesita menos altura','A una atmósfera, una columna de mercurio mide aproximadamente 76 cm. Una de agua necesitaría unos 10,3 m si despreciamos su vapor.','h = P atm / (ρg)'],['El vacío no tira del líquido','El aire exterior empuja el depósito; el líquido sube hasta equilibrar el peso de la columna. La presión baja de arriba permite ese desnivel.','Más presión exterior → columna más alta']]};
configs.syringe={title:'¿Vacío o sobrepresión? Depende de la referencia.',intro:'Una jeringa cerrada contiene aire. Al tirar del émbolo aumenta su volumen y baja su presión; al empujarlo ocurre lo contrario.',params:[['Volumen respecto al inicial',.3,2,1,.1,'×'],['Presión exterior',80,105,101,1,'kPa']],notes:'Gas ideal atrapado, temperatura constante, volumen inicial de 100 mL y presión inicial igual a la exterior. Émbolo de 1 cm², sin fricción. Su posición la prescribe el control: una mano debe sujetarlo si existe fuerza neta. El movimiento de los puntos es ilustrativo, no una simulación molecular.',lessons:[['Presión absoluta','Se mide desde el vacío ideal. No puede ser negativa en este modelo. Al duplicar el volumen, la presión absoluta del gas se reduce a la mitad.','P absoluta · V = constante'],['Presión manométrica','Compara el interior con el aire exterior. Puede ser negativa: eso significa presión menor que la atmosférica, no presión absoluta negativa.','P manométrica = P absoluta − P atm'],['¿Hacia dónde empuja?','Si dentro hay menos presión, el exterior empuja el émbolo hacia dentro. Si hay más, el gas lo empuja hacia fuera. La mano debe compensar esa fuerza para mantenerlo quieto.','F gas/aire sobre émbolo = ΔP · A']]};
const topicGroups={mechanics:['projectile','circle','pendulum','gears'],hydraulics:['compression','hydraulic','flow'],electricity:['current','alternator','threephase'],pneumatics:['pneumatic'],atmosphere:['atmosphere','barometer','syringe']};
let atmoParts=[],atmoDots=[],atmoSigns=[],atmoGauge;
const atmospherePressure=h=>101.325*Math.pow(1-.0065*h/288.15,5.25588);
function liveSign(position,width=3){const c=document.createElement('canvas');c.width=768;c.height=192;const tex=new THREE.CanvasTexture(c),sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}));sprite.position.copy(position);sprite.scale.set(width,width/4,1);sprite.renderOrder=10;group.add(sprite);return {c,tex,last:''};}
function writeSign(sign,value){if(sign.last===value)return;sign.last=value;const k=sign.c.getContext('2d');k.clearRect(0,0,768,192);k.fillStyle='rgba(12,28,24,.94)';k.beginPath();k.roundRect(6,6,756,180,24);k.fill();k.strokeStyle='#5e8a6c';k.lineWidth=3;k.stroke();k.fillStyle='#e3f4c7';k.textAlign='center';k.font='bold 58px monospace';k.fillText(value,384,118);sign.tex.needsUpdate=true;}
function pressureDial(x,y,z){const dial=mesh(new THREE.CylinderGeometry(.8,.8,.12,64),0x243c32);dial.rotation.x=Math.PI/2;dial.position.set(x,y,z);const rim=mesh(new THREE.TorusGeometry(.8,.04,8,64),0xa6bda1);rim.position.set(x,y,z+.08);for(let i=0;i<=10;i++){const angle=Math.PI*.85-i*Math.PI*1.7/10;const tick=mesh(new THREE.BoxGeometry(.025,.1,.02),0xdbe6c3);tick.position.set(x+Math.cos(angle)*.65,y+Math.sin(angle)*.65,z+.1);tick.rotation.z=angle-Math.PI/2;}const pointer=new THREE.Group();group.add(pointer);pointer.position.set(x,y,z+.13);const needle=mesh(new THREE.BoxGeometry(.56,.035,.025),0xe5ef83,pointer);needle.position.x=.28;mesh(new THREE.SphereGeometry(.08,12,8),0xcfdabb,pointer);return pointer;}

let electricParts=[],electricDots=[],electricRotor=null,phaseArrows=[],circuitCurve=null,supplyAC=false,pneumaticParts=[];
const phaseColors=[0xf4ce69,0x73dfce,0xbba3ff];
function makeCircuit(){const pts=[[-3,1.2,-1.6],[3,1.2,-1.6],[3,1.2,1.6],[-3,1.2,1.6],[-3,1.2,-1.6]].map(v=>new THREE.Vector3(...v));circuitCurve=new THREE.CurvePath();for(let i=1;i<pts.length;i++)circuitCurve.add(new THREE.LineCurve3(pts[i-1],pts[i]));mesh(new THREE.TubeGeometry(circuitCurve,100,.06,10,false),0x7faca5);const source=mesh(new THREE.BoxGeometry(.75,.7,1.3),0x65aba1);source.position.set(-3,1.3,0);const resistor=mesh(new THREE.BoxGeometry(.65,.5,1.2),0xe9ba6d);resistor.position.set(3,1.3,0);electricParts=[resistor];label('FUENTE',new THREE.Vector3(-3,.1,2.3),.45);label('RESISTENCIA',new THREE.Vector3(3,.1,2.3),.45);electricDots=[];for(let i=0;i<28;i++){const dot=mesh(new THREE.SphereGeometry(.08,12,8),0xe9f99f);dot.userData.phase=i/28;electricDots.push(dot)}}
function drawElectricWave(theta){const svg=$('#electricWave');if(!svg)return;const count=mode==='threephase'?3:1;let html='<path d="M35 70H565 M35 15V125" stroke="#547364" fill="none"/>';for(let j=0;j<count;j++){const shift=j*2*Math.PI/3,color='#'+phaseColors[j].toString(16);let d='';for(let i=0;i<=180;i++){const angle=i/180*Math.PI*2,v=mode==='current'&&!supplyAC?1:Math.sin(angle-shift);d+=(i?'L':'M')+(35+i/180*530).toFixed(2)+' '+(70-v*48).toFixed(2)}html+='<path d="'+d+'" stroke="'+color+'" fill="none" stroke-width="2.5"/>'}const x=35+((theta%(Math.PI*2)+Math.PI*2)%(Math.PI*2))/(Math.PI*2)*530;html+='<path d="M'+x+' 15V125" stroke="#eff5dd" stroke-dasharray="4 4"/>';html+='<text x="35" y="145" fill="#b5c7b6" font-size="11">0°</text><text x="290" y="145" fill="#b5c7b6" font-size="11">180°</text><text x="535" y="145" fill="#b5c7b6" font-size="11">360°</text>';svg.innerHTML=html;}

let hydroParts=[],fluidParts=[],molecules=[],flowLookup=[];
function glassCylinder(r,height,x){const wall=mesh(new THREE.CylinderGeometry(r,r,height,48,1,true),0x83c6c7);wall.material.transparent=true;wall.material.opacity=.16;wall.material.depthWrite=false;wall.material.side=THREE.DoubleSide;wall.position.set(x,height/2+.3,0);for(const y of [.3,height+.3]){const ring=mesh(new THREE.TorusGeometry(r,.035,8,48),0x7ea5a0);ring.rotation.x=Math.PI/2;ring.position.set(x,y,0)}return wall;}
function piston(r,x,y){const root=new THREE.Group();group.add(root);mesh(new THREE.CylinderGeometry(r,r,.16,48),0xc5d0bc,root);const stem=mesh(new THREE.CylinderGeometry(.09,.09,1.1,20),0x8eaa9e,root);stem.position.y=.6;const cap=mesh(new THREE.CylinderGeometry(r*.7,r*.7,.12,32),0xd9ef66,root);cap.position.y=1.2;root.position.set(x,y,0);return root;}
function waterColumn(r,x,height){const m=mesh(new THREE.CylinderGeometry(r,r,1,48),0x3cbbbb);m.material.transparent=true;m.material.opacity=.5;m.material.depthWrite=false;m.position.set(x,height/2+.3,0);m.scale.y=height;return m;}

let mode='projectile',vals=[14,45],t=0,duration=1,rate=1,run=!matchMedia('(prefers-reduced-motion: reduce)').matches,visible=false,scene,camera,renderer,orbit,group,body,velocity,acceleration,gearA,gearB,barK,barP,pendulumSamples=[],lengthScale=1,last=0;
const world=$('#world');
try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.setClearColor(0x14251f);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.4;world.prepend(renderer.domElement);renderer.domElement.setAttribute('aria-label','Escenario 3D interactivo. Usa los controles de vista para cambiar la cámara.');scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x14251f,.012);camera=new THREE.PerspectiveCamera(40,1,.05,500);orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.maxPolarAngle=Math.PI*.49;orbit.minDistance=3;orbit.maxDistance=160;scene.add(new THREE.HemisphereLight(0xf0ffd8,0x233d33,3));const sun=new THREE.DirectionalLight(0xfff1ce,4);sun.position.set(-10,25,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-40,right:40,top:40,bottom:-40,far:100});sun.shadow.bias=-.0003;scene.add(sun);const rim=new THREE.DirectionalLight(0x76d9c4,2);rim.position.set(15,8,-10);scene.add(rim);}catch(e){world.insertAdjacentHTML('beforeend','<p class="webgl-error">No se pudo iniciar el escenario 3D. Activa la aceleración gráfica del navegador y recarga la página. Las lecciones del módulo 01 siguen disponibles.</p>');throw e;}
const mat=(color,metalness=.25)=>new THREE.MeshStandardMaterial({color,roughness:.32,metalness});
function mesh(geometry,color,parent=group){const m=new THREE.Mesh(geometry,mat(color));m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function tube(points,color,r=.025){return mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),180,r,6,false),color)}
